import * as ts from 'typescript';
export interface TestFrameworkPar {
    testMode: string;
    coverageMode?: string;
}
export interface ProjectConfig {
    needCoverageInsert?: boolean;
    testFrameworkPar: TestFrameworkPar;
    modulePath: string;
    projectTopDir: string;
    etsLoaderPath?: string;
}
export interface ModuleSourceFile {
    isSourceNode: boolean;
    moduleId: string;
    source: ts.SourceFile;
}
export interface CacheInterface {
    get(key: string): unknown;
    set(key: string, value: unknown): void;
}
export interface ShareInterface {
    projectConfig: ProjectConfig;
    ModuleSourceFile: ModuleSourceFile[];
}
export interface BuildInstrumentContext {
    cache: CacheInterface;
    share: ShareInterface;
}
